const MAX_N = 100_000;
const MOD = 10n ** 9n + 7n;
const pow10 = new Array(MAX_N + 1);

pow10[0] = 1n;
for (let i = 1; i <= MAX_N; i++) {
    pow10[i] = (pow10[i - 1] * 10n) % MOD;
}

/**
 * @param {string} s
 * @param {number[][]} queries
 * @return {number[]}
 */
var sumAndMultiply = function(s, queries) {
    const dpX = Array(s.length + 1).fill(0n);
    const dpSum = Array(s.length + 1).fill(0n);
    const dpLen = Array(s.length + 1).fill(0n);

    for (let i = 0; i < s.length; i++) {
        const cur = BigInt(s[i]);
        dpX[i + 1] = cur > 0 ? (dpX[i] * 10n + cur) % MOD : dpX[i];
        dpSum[i + 1] = dpSum[i] + cur;
        dpLen[i + 1] = dpLen[i] + (cur > 0 ? 1n : 0n);
    }

    const res = [];

    for (const [l, r] of queries) {
        const len = dpLen[r + 1] - dpLen[l];
        const x = (dpX[r + 1] - ((dpX[l] * pow10[len]) % MOD) + MOD) % MOD;
        const sum = dpSum[r + 1] - dpSum[l];
        res.push(Number((x * sum) % MOD));
    }

    return res;
};
